"""Pure-python age crypto primitives, for black-box verification of the binary."""
import hashlib, hmac, struct, os

# ---------------- bech32 ----------------
CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"
def bech32_polymod(values):
    GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3]
    chk = 1
    for v in values:
        b = chk >> 25
        chk = (chk & 0x1ffffff) << 5 ^ v
        for i in range(5):
            chk ^= GEN[i] if ((b >> i) & 1) else 0
    return chk
def bech32_hrp_expand(hrp):
    return [ord(x) >> 5 for x in hrp] + [0] + [ord(x) & 31 for x in hrp]
def bech32_verify_checksum(hrp, data):
    return bech32_polymod(bech32_hrp_expand(hrp) + data) == 1
def bech32_create_checksum(hrp, data):
    values = bech32_hrp_expand(hrp) + data
    polymod = bech32_polymod(values + [0,0,0,0,0,0]) ^ 1
    return [(polymod >> 5 * (5 - i)) & 31 for i in range(6)]
def bech32_encode(hrp, data):
    combined = data + bech32_create_checksum(hrp, data)
    return hrp + '1' + ''.join([CHARSET[d] for d in combined])
def bech32_decode(bech):
    b = bech.lower()
    pos = b.rfind('1')
    hrp = b[:pos]; data = [CHARSET.find(c) for c in b[pos+1:]]
    assert bech32_verify_checksum(hrp, data), "bad checksum"
    return hrp, data[:-6]
def convertbits(data, frombits, tobits, pad=True):
    acc = 0; bits = 0; ret = []
    maxv = (1 << tobits) - 1
    for value in data:
        acc = (acc << frombits) | value
        bits += frombits
        while bits >= tobits:
            bits -= tobits
            ret.append((acc >> bits) & maxv)
    if pad and bits:
        ret.append((acc << (tobits - bits)) & maxv)
    return ret
def bech32_to_bytes(s):
    hrp, data = bech32_decode(s)
    return hrp, bytes(convertbits(data, 5, 8, False))
def bytes_to_bech32(hrp, b):
    return bech32_encode(hrp, convertbits(list(b), 8, 5))

# ---------------- X25519 ----------------
P = 2**255 - 19
A24 = 121665
def _cswap(swap, x2, x3):
    return (x3, x2) if swap else (x2, x3)
def x25519(k: bytes, u: bytes) -> bytes:
    k = bytearray(k); k[0] &= 248; k[31] &= 127; k[31] |= 64
    kk = int.from_bytes(k, 'little')
    x1 = int.from_bytes(u, 'little') % (2**255)
    x2, z2, x3, z3, swap = 1, 0, x1, 1, 0
    for t in range(254, -1, -1):
        kt = (kk >> t) & 1
        swap ^= kt
        x2, x3 = _cswap(swap, x2, x3); z2, z3 = _cswap(swap, z2, z3)
        swap = kt
        a = (x2 + z2) % P; aa = a*a % P
        b = (x2 - z2) % P; bb = b*b % P
        e = (aa - bb) % P
        c = (x3 + z3) % P; d = (x3 - z3) % P
        da = d*a % P; cb = c*b % P
        x3 = pow((da + cb) % P, 2, P)
        z3 = x1 * pow((da - cb) % P, 2, P) % P
        x2 = aa*bb % P
        z2 = e * ((aa + A24*e) % P) % P
    x2, x3 = _cswap(swap, x2, x3); z2, z3 = _cswap(swap, z2, z3)
    return (x2 * pow(z2, P-2, P) % P).to_bytes(32, 'little')
BASE9 = (9).to_bytes(32, 'little')
def x25519_pub(sk): return x25519(sk, BASE9)

# ---------------- ChaCha20-Poly1305 (RFC 8439) ----------------
def _rotl(v, c): return ((v << c) | (v >> (32 - c))) & 0xffffffff
def chacha20_block(key, counter, nonce):
    st = list(struct.unpack('<4I', b'expand 32-byte k')) + list(struct.unpack('<8I', key)) \
         + [counter] + list(struct.unpack('<3I', nonce))
    x = list(st)
    def qr(a, b, c, d):
        x[a] = (x[a] + x[b]) & 0xffffffff; x[d] = _rotl(x[d] ^ x[a], 16)
        x[c] = (x[c] + x[d]) & 0xffffffff; x[b] = _rotl(x[b] ^ x[c], 12)
        x[a] = (x[a] + x[b]) & 0xffffffff; x[d] = _rotl(x[d] ^ x[a], 8)
        x[c] = (x[c] + x[d]) & 0xffffffff; x[b] = _rotl(x[b] ^ x[c], 7)
    for _ in range(10):
        qr(0,4,8,12); qr(1,5,9,13); qr(2,6,10,14); qr(3,7,11,15)
        qr(0,5,10,15); qr(1,6,11,12); qr(2,7,8,13); qr(3,4,9,14)
    return struct.pack('<16I', *[(x[i] + st[i]) & 0xffffffff for i in range(16)])
def chacha20(key, counter, nonce, data):
    out = bytearray()
    for i in range(0, len(data), 64):
        ks = chacha20_block(key, counter + i // 64, nonce)
        blk = data[i:i+64]
        out += bytes(a ^ b for a, b in zip(blk, ks))
    return bytes(out)
def poly1305(key, msg):
    r = int.from_bytes(key[:16], 'little') & 0x0ffffffc0ffffffc0ffffffc0fffffff
    s = int.from_bytes(key[16:], 'little')
    p = (1 << 130) - 5
    acc = 0
    for i in range(0, len(msg), 16):
        blk = msg[i:i+16]
        n = int.from_bytes(blk + b'\x01', 'little')
        acc = (acc + n) * r % p
    return ((acc + s) & ((1 << 128) - 1)).to_bytes(16, 'little')
def _pad16(b): return b'\x00' * ((-len(b)) % 16)
def aead_seal(key, nonce, pt, aad=b''):
    otk = chacha20_block(key, 0, nonce)[:32]
    ct = chacha20(key, 1, nonce, pt)
    mac_data = aad + _pad16(aad) + ct + _pad16(ct) + struct.pack('<QQ', len(aad), len(ct))
    return ct + poly1305(otk, mac_data)
def aead_open(key, nonce, ct_tag, aad=b''):
    ct, tag = ct_tag[:-16], ct_tag[-16:]
    otk = chacha20_block(key, 0, nonce)[:32]
    mac_data = aad + _pad16(aad) + ct + _pad16(ct) + struct.pack('<QQ', len(aad), len(ct))
    if not hmac.compare_digest(poly1305(otk, mac_data), tag):
        raise ValueError('auth fail')
    return chacha20(key, 1, nonce, ct)

# ---------------- HKDF-SHA256 ----------------
def hkdf(salt, info, ikm, length=32):
    prk = hmac.new(salt, ikm, hashlib.sha256).digest()
    out = b''; t = b''; i = 1
    while len(out) < length:
        t = hmac.new(prk, t + info + bytes([i]), hashlib.sha256).digest()
        out += t; i += 1
    return out[:length]

# ---------------- base64 (age flavour: raw std, no padding) ----------------
import base64
def b64(b): return base64.b64encode(b).decode().rstrip('=')
def unb64(s):
    s = s.strip()
    return base64.b64decode(s + '=' * ((-len(s)) % 4))

# ---------------- STREAM ----------------
CHUNK = 65536
def stream_key(file_key, nonce):
    return hkdf(nonce, b'payload', file_key, 32)
def stream_nonce(counter, last):
    return counter.to_bytes(11, 'big') + (b'\x01' if last else b'\x00')
def stream_encrypt(file_key, pt, nonce16=None):
    if nonce16 is None: nonce16 = os.urandom(16)
    k = stream_key(file_key, nonce16)
    out = bytearray(nonce16)
    chunks = [pt[i:i+CHUNK] for i in range(0, len(pt), CHUNK)] or [b'']
    for i, c in enumerate(chunks):
        last = (i == len(chunks) - 1)
        out += aead_seal(k, stream_nonce(i, last), c)
    return bytes(out)
def stream_decrypt(file_key, payload):
    nonce16, rest = payload[:16], payload[16:]
    k = stream_key(file_key, nonce16)
    out = bytearray(); i = 0
    while rest:
        blk = rest[:CHUNK+16]; rest = rest[CHUNK+16:]
        last = (len(rest) == 0)
        try:
            out += aead_open(k, stream_nonce(i, last), blk)
        except ValueError:
            if last: raise
            raise
        i += 1
    return bytes(out)

# ---------------- header ----------------
HDR_INTRO = b'age-encryption.org/v1\n'
def parse_header(data):
    """returns (stanzas, mac, header_bytes_len, payload)"""
    assert data.startswith(HDR_INTRO), data[:30]
    i = len(HDR_INTRO)
    stanzas = []
    while True:
        assert data[i:i+3] in (b'-> ', b'---'), data[i:i+10]
        if data[i:i+4] == b'--- ':
            j = data.index(b'\n', i)
            mac = unb64(data[i+4:j].decode())
            return stanzas, mac, j+1, data[j+1:]
        j = data.index(b'\n', i)
        args = data[i+3:j].decode().split(' ')
        i = j + 1
        body = b''
        while True:
            j = data.index(b'\n', i)
            line = data[i:j]
            i = j + 1
            body += unb64(line.decode())
            if len(line) < 64:
                break
        stanzas.append((args, body))
def hdr_no_mac(stanzas):
    out = bytearray(HDR_INTRO)
    for args, body in stanzas:
        out += b'-> ' + ' '.join(args).encode() + b'\n'
        s = b64(body)
        if s == '': lines = ['']
        else: lines = [s[i:i+64] for i in range(0, len(s), 64)]
        if len(lines[-1]) == 64: lines.append('')
        for l in lines: out += l.encode() + b'\n'
    out += b'---'
    return bytes(out)
def header_mac(file_key, stanzas):
    hk = hkdf(b'', b'header', file_key, 32)
    return hmac.new(hk, hdr_no_mac(stanzas), hashlib.sha256).digest()

def x25519_unwrap(ident_sk, share, wrapped):
    shared = x25519(ident_sk, share)
    salt = share + x25519_pub(ident_sk)
    wk = hkdf(salt, b'age-encryption.org/v1/X25519', shared, 32)
    return aead_open(wk, b'\x00'*12, wrapped)
def x25519_wrap(recip_pub, file_key, eph_sk=None):
    if eph_sk is None: eph_sk = os.urandom(32)
    share = x25519_pub(eph_sk)
    shared = x25519(eph_sk, recip_pub)
    salt = share + recip_pub
    wk = hkdf(salt, b'age-encryption.org/v1/X25519', shared, 32)
    return share, aead_seal(wk, b'\x00'*12, file_key)

